package caseapp

import caseapp.core.complete.{CompletionItem, Zsh}
import utest._

object ZshCompletionTests extends TestSuite {

  private lazy val hasZsh =
    !scala.util.Properties.isWin &&
    scala.util.Try(os.proc("zsh", "-f", "-c", "true").call(check = false).exitCode == 0)
      .getOrElse(false)

  // Evaluates a snippet produced by Zsh.print the way the function generated by
  // Zsh.script does, with _describe and _files replaced by functions printing what
  // they're passed
  private def zshEntries(snippet: String): Seq[String] = {
    val script =
      """_describe() { print -rl -- "${(@P)2}" }
        |_files() { print -r -- "<files>" }
        |eval "$1"
        |""".stripMargin
    os.proc("zsh", "-f", "-c", script, "zsh", snippet)
      .call()
      .out
      .lines()
      .filter(_.nonEmpty)
  }

  val tests = Tests {
    test("values and descriptions are taken literally") {
      if (hasZsh) {
        val items = Seq(
          CompletionItem("it's", Some("Don't $HOME `pwd` $(echo no) | \\"), Nil),
          CompletionItem("org:name", Some("Ends with a backslash \\"), Seq("--opt"))
        )
        val entries = zshEntries(Zsh.print(items))
        val expected = Seq(
          "it's:Don't $HOME `pwd` $(echo no) | \\",
          // _describe splits entries on the first unescaped ':'
          "org\\:name:Ends with a backslash \\",
          "--opt:Ends with a backslash \\"
        )
        assert(entries == expected)
      }
      else
        "zsh not available, skipped"
    }
  }
}
